import React from 'react';

const App = () => {
  return (
    <div className="lp-container">
      {/* デザインを定義する専用スタイル */}
      <style dangerouslySetInnerHTML={{ __html: `
        @import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Noto+Sans+JP:wght@900&display=swap');

        :root {
          --j-red: #C22222;
          --j-yellow: #FFD700;
          --j-blue: #005BAC;
          --j-black: #1A1A1A;
        }

        .lp-container {
          background-color: var(--j-black);
          color: #fff;
          font-family: 'Noto Sans JP', sans-serif;
          line-height: 1.2;
          overflow-x: hidden;
        }

        /* 縁取り文字の強化：より「ロゴ」らしく */
        .text-stroke-heavy {
          paint-order: stroke fill;
          -webkit-text-stroke: 8px var(--j-black);
          text-shadow: 6px 6px 0px var(--j-black);
        }

        .letter-spacing-tight {
          letter-spacing: -0.05em;
        }

        /* 集中線のグラデーション */
        .radial-lines {
          background: radial-gradient(circle, transparent 30%, var(--j-black) 80%),
                      repeating-conic-gradient(from 0deg, #333 0deg 10deg, transparent 10deg 20deg);
          position: absolute;
          inset: 0;
          opacity: 0.4;
        }

        /* 装飾的なボックス */
        .manga-box {
          border: 4px solid var(--j-black);
          box-shadow: 8px 8px 0px 0px var(--j-black);
        }
      `}} />

      {/* --- HERO SECTION --- */}
      <section className="relative pt-24 pb-32 overflow-hidden bg-[#D32F2F]">
        <div className="radial-lines"></div>

        <div className="relative z-10 container mx-auto px-4 text-center">
          {/* サブキャッチ */}
          <div className="inline-block bg-black text-white px-4 py-1 mb-6 font-black text-xl transform -skew-x-12 letter-spacing-tight">
            週刊少年ジャンプ 掲載順位速報
          </div>

          {/* メインタイトル：字間を詰めてインパクト大 */}
          <h1 className="flex flex-col items-center mb-10 leading-none">
            <span className="text-white text-5xl md:text-7xl font-black letter-spacing-tight text-stroke-heavy italic mb-2">
              ジャンプ順位<span className="text-yellow-400">Webアプリ</span>
            </span>
            <span className="text-yellow-400 text-8xl md:text-[10rem] font-black italic letter-spacing-tight text-stroke-heavy transform -rotate-2">
              登場!!
